<?php use Hls\Http\View as V; ?><section class="panel"><p>Barang: <strong><?= V::escape($product['code'].' - '.$product['name']) ?></strong></p><p>Gudang: <?= $warehouse_id ? (int)$warehouse_id : 'Belum dialokasikan' ?></p></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Referensi</th><th>Jenis</th><th>Masuk</th><th>Keluar</th><th>Saldo Berjalan</th></tr></thead><tbody><?php $balance=$opening_balance ?? 0; foreach($rows as $r): $balance+=(float)$r['quantity_change']; ?><tr><td><?= V::escape($r['transaction_date']) ?></td><td><?= V::escape((string)$r['reference_type'].' #'.(string)$r['reference_id']) ?></td><td><?= V::escape($r['transaction_type']) ?></td><td><?= number_format((float)$r['qty_in'],3,',','.') ?></td><td><?= number_format((float)$r['qty_out'],3,',','.') ?></td><td><?= number_format($balance,3,',','.') ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Belum ada mutasi stok.</td></tr><?php endif ?></tbody></table></div></section><?php if($pages>1): ?><nav class="pagination">Halaman <?= (int)$page ?> dari <?= (int)$pages ?></nav><?php endif ?><a class="button" href="<?= $this->url('/inventory/stocks') ?>">Kembali</a>

